package hook

import (
	"fmt"
	"strings"
)

const (
	// HookName is the Git hook this package manages.
	HookName = "prepare-commit-msg"

	// BackupSuffix is appended to the hook path when --force replaces a
	// foreign hook.
	BackupSuffix = ".gptcomet-backup"

	// ManagedMarker identifies a hook generated by gmsg.
	ManagedMarker = "# gptcomet-managed-hook"
)

// scriptTemplate is a POSIX shell wrapper. It deliberately contains all of the
// conditional logic needed to remain fail-open; the real decision logic lives
// in `gmsg hook run`.
const scriptTemplate = `#!/bin/sh
# gptcomet-managed-hook
# Generated by gmsg. Remove with: gmsg hook uninstall

bin="${GMSG_BIN:-gmsg}"
command -v "$bin" >/dev/null 2>&1 || exit 0

config=%s
if [ -n "${GMSG_CONFIG:-}" ]; then
  config="$GMSG_CONFIG"
fi

run_hook() {
  if [ -n "$config" ]; then
    "$bin" --config "$config" hook run "$@"
  else
    "$bin" hook run "$@"
  fi
}

if [ "${GMSG_HOOK_DEBUG:-}" = "1" ]; then
  run_hook "$@" || exit 0
else
  run_hook "$@" >/dev/null 2>&1 || exit 0
fi
exit 0
`

func buildScript(configPath string) string {
	quoted := "''"
	if strings.TrimSpace(configPath) != "" {
		quoted = shellQuote(configPath)
	}
	return fmt.Sprintf(scriptTemplate, quoted)
}

func isManagedHook(script string) bool {
	return strings.Contains(script, ManagedMarker)
}

// shellQuote quotes a value for POSIX sh single-quoted strings.
func shellQuote(value string) string {
	return "'" + strings.ReplaceAll(value, "'", `'\''`) + "'"
}
